import json, base64

DATA = json.loads(base64.b64decode("").decode("utf-8"))

# P Practicals (P1-P11) and Jira Practical (J0-J20), same shape as DATA.
# Book practicals above are unchanged; these sections are only added.
DATA_P = json.loads(base64.b64decode("").decode("utf-8"))
DATA_JIRA = json.loads(base64.b64decode("").decode("utf-8"))

SEP = "# " + "=" * 70


def build_plain():
    out = []
    for section_title, items in (("Practical Book", DATA),
                                 ("P Practicals", DATA_P),
                                 ("Jira Practical", DATA_JIRA)):
        out.append(SEP)
        out.append("# " + section_title)
        out.append(SEP)
        out.append("")
        for it in items:
            out.append(SEP)
            out.append("# " + it["name"])
            out.append(SEP)
            out.append(it["code"].rstrip())
            out.append("")
            out.append("")
    return "\n".join(out).rstrip() + "\n"


def build_html():
    sections = [{"title": "Practical Book", "items": DATA},
                {"title": "P Practicals", "items": DATA_P},
                {"title": "Jira Practical", "items": DATA_JIRA}]
    sections_json = json.dumps(sections, ensure_ascii=False).replace("</", "<\\/")
    return PAGE.replace("__SECTIONS_JSON__", sections_json)


